# ==========================================\n# MÓDULO DE AYUDANTES PARA FORMULARIOS\n# ==========================================\n\"\"\"Funciones helper para mejorar la experiencia de formularios.\"\"\"\n\nimport streamlit as st\nfrom datetime import datetime\nfrom typing import Dict, Any, Callable, Optional\n\n\nclass GestorFormularios:\n    \"\"\"Gestiona formularios con confirmación y validación mejorada.\"\"\"\n\n    @staticmethod\n    def mostrar_confirmacion_exitosa(\n        tipo_accion: str,\n        nombre_entidad: str,\n        datos: Dict[str, Any],\n        duracion: int = 5\n    ):\n        \"\"\"Muestra confirmación exitosa con detalles.\n        \n        Args:\n            tipo_accion: 'crear', 'actualizar', 'eliminar'\n            nombre_entidad: 'Socio', 'Ahorro', 'Préstamo', etc\n            datos: Diccionario con datos registrados\n            duracion: Segundos de visualización\n        \"\"\"\n        emojis = {\n            'crear': '✨',\n            'actualizar': '📝',\n            'eliminar': '🗑️',\n            'pago': '✅',\n            'egreso': '💸'\n        }\n        \n        emoji = emojis.get(tipo_accion, '✨')\n        \n        mensajes = {\n            'crear': f\"¡{emoji} {nombre_entidad} CREADO exitosamente!\",\n            'actualizar': f\"¡{emoji} {nombre_entidad} ACTUALIZADO correctamente!\",\n            'eliminar': f\"¡{emoji} {nombre_entidad} ELIMINADO del sistema!\",\n            'pago': f\"¡{emoji} Pago registrado correctamente!\",\n            'egreso': f\"¡{emoji} Egreso registrado!\"\n        }\n        \n        mensaje = mensajes.get(tipo_accion, f\"¡{emoji} Operación realizada!\")\n        \n        # Mostrar success con animación\n        success_container = st.success(mensaje)\n        \n        # Mostrar detalles\n        with st.expander(\"📋 Detalles registrados\", expanded=True):\n            col1, col2 = st.columns(2)\n            for i, (clave, valor) in enumerate(datos.items()):\n                if i % 2 == 0:\n                    with col1:\n                        st.write(f\"**{clave}:** {valor}\")\n                else:\n                    with col2:\n                        st.write(f\"**{clave}:** {valor}\")\n        \n        # Timestamp de operación\n        st.caption(f\"⏰ {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\")\n\n    @staticmethod\n    def reiniciar_formulario(clave_form: str = None):\n        \"\"\"Reinicia el formulario después de guardar.\n        \n        Args:\n            clave_form: Clave del formulario a reiniciar (opcional)\n        \"\"\"\n        if clave_form:\n            if clave_form in st.session_state:\n                del st.session_state[clave_form]\n        \n        # Esperar un poco para que vea la confirmación\n        import time\n        time.sleep(1.5)\n        st.rerun()\n\n    @staticmethod\n    def mostrar_resumen_insercion(\n        tipo: str,\n        nombre: str,\n        detalles: Dict[str, Any],\n        con_botones: bool = True\n    ):\n        \"\"\"Muestra un resumen formateado de lo que se insertó.\n        \n        Args:\n            tipo: Tipo de registro (socio, ahorro, préstamo, etc)\n            nombre: Nombre/ID del registro\n            detalles: Diccionario con detalles\n            con_botones: Si mostrar botones de acción adicional\n        \"\"\"\n        st.markdown(\"---\")\n        \n        # Encabezado\n        st.markdown(f\"### ✅ Resumen de {tipo.upper()}\")\n        \n        # Tabla de resumen\n        col1, col2 = st.columns(2)\n        \n        with col1:\n            st.markdown(f\"**Nombre/ID:** `{nombre}`\")\n            st.markdown(f\"**Tipo:** `{tipo}`\")\n        \n        with col2:\n            st.markdown(f\"**Fecha:** `{datetime.now().strftime('%Y-%m-%d')}`\")\n            st.markdown(f\"**Hora:** `{datetime.now().strftime('%H:%M:%S')}`\")\n        \n        # Detalles adicionales\n        if detalles:\n            st.markdown(\"**Detalles registrados:**\")\n            for clave, valor in detalles.items():\n                if valor is not None and valor != \"\":\n                    st.markdown(f\"- **{clave}:** `{valor}`\")\n        \n        if con_botones:\n            col_btn1, col_btn2, col_btn3 = st.columns(3)\n            with col_btn1:\n                if st.button(\"➕ Registrar otro\", use_container_width=True):\n                    st.session_state.mostrar_form = True\n                    st.rerun()\n            with col_btn2:\n                if st.button(\"📊 Ver listado\", use_container_width=True):\n                    st.session_state.mostrar_listado = True\n                    st.rerun()\n            with col_btn3:\n                if st.button(\"🏠 Ir al inicio\", use_container_width=True):\n                    st.switch_page(\"pages/inicio.py\" if \"pages/inicio.py\" else \"App.py\")\n\n    @staticmethod\n    def confirmacion_eliminar(\n        nombre_entidad: str,\n        descripcion: str,\n        datos_advertencia: Dict[str, Any] = None\n    ) -> bool:\n        \"\"\"Muestra una confirmación antes de eliminar.\n        \n        Args:\n            nombre_entidad: Nombre de lo que se va a eliminar\n            descripcion: Descripción del elemento\n            datos_advertencia: Datos que podrían ser críticos\n            \n        Returns:\n            True si confirma eliminación\n        \"\"\"\n        st.warning(\n            f\"⚠️ ATENCIÓN: Estás a punto de eliminar **{nombre_entidad}**\\n\\n\"\n            f\"**{descripcion}**\\n\\n\"\n            f\"❌ Esta acción **NO se puede deshacer**.\"\n        )\n        \n        if datos_advertencia:\n            st.markdown(\"**Datos que se eliminarán:**\")\n            for clave, valor in datos_advertencia.items():\n                st.markdown(f\"- {clave}: `{valor}`\")\n        \n        confirmacion = st.checkbox(\n            f\"✓ Confirmo que deseo ELIMINAR {nombre_entidad.lower()}\",\n            key=f\"confirmar_delete_{nombre_entidad}\"\n        )\n        \n        return confirmacion\n\n    @staticmethod\n    def mostrar_confirmacion_actualizacion(\n        campos_anteriores: Dict[str, Any],\n        campos_nuevos: Dict[str, Any]\n    ):\n        \"\"\"Muestra las diferencias entre datos anteriores y nuevos.\n        \n        Args:\n            campos_anteriores: Datos originales\n            campos_nuevos: Datos actualizados\n        \"\"\"\n        st.markdown(\"### 📊 Cambios a realizar\")\n        \n        cambios = {}\n        for clave in campos_anteriores.keys():\n            if campos_anteriores[clave] != campos_nuevos.get(clave):\n                cambios[clave] = {\n                    'anterior': campos_anteriores[clave],\n                    'nuevo': campos_nuevos.get(clave)\n                }\n        \n        if not cambios:\n            st.info(\"ℹ️ No hay cambios para realizar.\")\n            return False\n        \n        for clave, valores in cambios.items():\n            col1, col2, col3 = st.columns([2, 1, 2])\n            with col1:\n                st.write(f\"**Anterior:** `{valores['anterior']}`\")\n            with col2:\n                st.write(\"→\")\n            with col3:\n                st.write(f\"**Nuevo:** `{valores['nuevo']}`\")\n        \n        return True\n\n    @staticmethod\n    def mostrar_progreso_operacion(\n        pasos: list,\n        paso_actual: int,\n        descripcion: str = \"\"\n    ):\n        \"\"\"Muestra una barra de progreso con pasos.\n        \n        Args:\n            pasos: Lista de pasos a realizar\n            paso_actual: Número del paso actual (1-indexed)\n            descripcion: Descripción del paso actual\n        \"\"\"\n        progreso = (paso_actual - 1) / len(pasos)\n        st.progress(progreso)\n        \n        col1, col2 = st.columns([3, 1])\n        with col1:\n            st.write(f\"**{pasos[paso_actual-1]}**\")\n            if descripcion:\n                st.caption(descripcion)\n        with col2:\n            st.metric(\"Progreso\", f\"{paso_actual}/{len(pasos)}\")\n\n    @staticmethod\n    def crear_formulario_dinamico(\n        campos: Dict[str, Dict[str, Any]],\n        titulo: str = \"Formulario\",\n        boton_enviar: str = \"Guardar\"\n    ) -> Dict[str, Any]:\n        \"\"\"Crea un formulario dinámico basado en especificación de campos.\n        \n        Args:\n            campos: Diccionario con especificación de campos\n                    Ejemplo: {\n                        'nombre': {'tipo': 'text', 'label': 'Nombre', 'required': True},\n                        'edad': {'tipo': 'number', 'label': 'Edad', 'min': 0, 'max': 120},\n                        'estado': {'tipo': 'selectbox', 'label': 'Estado', 'options': ['Activo', 'Inactivo']}\n                    }\n            titulo: Título del formulario\n            boton_enviar: Texto del botón enviar\n            \n        Returns:\n            Diccionario con valores del formulario\n        \"\"\"\n        st.subheader(titulo)\n        \n        resultados = {}\n        with st.form(f\"form_{titulo.lower().replace(' ', '_')}\", clear_on_submit=True):\n            for campo_nombre, config in campos.items():\n                tipo_campo = config.get('tipo', 'text')\n                label = config.get('label', campo_nombre)\n                required = config.get('required', False)\n                \n                label_completo = f\"{label}\" + (\" *\" if required else \"\")\n                \n                if tipo_campo == 'text':\n                    resultados[campo_nombre] = st.text_input(\n                        label_completo,\n                        value=config.get('value', ''),\n                        placeholder=config.get('placeholder', '')\n                    )\n                \n                elif tipo_campo == 'number':\n                    resultados[campo_nombre] = st.number_input(\n                        label_completo,\n                        value=config.get('value', 0),\n                        min_value=config.get('min', None),\n                        max_value=config.get('max', None),\n                        step=config.get('step', 1)\n                    )\n                \n                elif tipo_campo == 'date':\n                    resultados[campo_nombre] = st.date_input(\n                        label_completo,\n                        value=config.get('value', datetime.now())\n                    )\n                \n                elif tipo_campo == 'selectbox':\n                    resultados[campo_nombre] = st.selectbox(\n                        label_completo,\n                        config.get('options', []),\n                        index=config.get('index', 0)\n                    )\n                \n                elif tipo_campo == 'textarea':\n                    resultados[campo_nombre] = st.text_area(\n                        label_completo,\n                        value=config.get('value', ''),\n                        placeholder=config.get('placeholder', '')\n                    )\n            \n            if st.form_submit_button(boton_enviar, use_container_width=True):\n                # Validar campos requeridos\n                for campo_nombre, config in campos.items():\n                    if config.get('required', False) and not resultados[campo_nombre]:\n                        st.error(f\"El campo '{config.get('label', campo_nombre)}' es obligatorio.\")\n                        return None\n                return resultados\n        \n        return None\n\n    @staticmethod\n    def mostrar_notificacion(\n        tipo: str,\n        titulo: str,\n        mensaje: str,\n        duracion: int = 3,\n        icono: str = \"\"\n    ):\n        \"\"\"Muestra una notificación personalizada.\n        \n        Args:\n            tipo: 'success', 'error', 'warning', 'info'\n            titulo: Título de la notificación\n            mensaje: Mensaje detallado\n            duracion: Segundos de visualización\n            icono: Emoji personalizado\n        \"\"\"\n        if tipo == 'success':\n            st.success(f\"{icono or '✅'} **{titulo}**\\n\\n{mensaje}\")\n        elif tipo == 'error':\n            st.error(f\"{icono or '❌'} **{titulo}**\\n\\n{mensaje}\")\n        elif tipo == 'warning':\n            st.warning(f\"{icono or '⚠️'} **{titulo}**\\n\\n{mensaje}\")\n        else:\n            st.info(f\"{icono or 'ℹ️'} **{titulo}**\\n\\n{mensaje}\")\n"